  get('#jumpAnswer').click();
  jumpSeq.push(Number(get('#answerPageInput').value));
}
check('+3跳转序列（并在 33 页封顶）', jumpSeq.join(','), '23,26,29,32,33');
check('+3跳转后图片同步', get('#answerImage').src, 'assets/answers/aux-practice/page-33.jpg');
